    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next((c for row in grid for c, v in enumerate(row) if v == 2), 0)
    bars = [r for r, row in enumerate(grid) if 8 in row]
    gaps = [[c for c, v in enumerate(grid[r]) if v == 0] for r in bars]
    if not bars:
        return out
    # Approach the first barrier from the marker, turn toward its nearest gap.
    for r in range(bars[0]):
        out[r][marker] = 2
    first = min(gaps[0], key=lambda c: (abs(c - marker), c))
    for c in range(min(marker, first), max(marker, first) + 1):
        out[bars[0] - 1][c] = 2
    out[bars[0]][first] = 2
    # Connect successive barrier openings through their intervening channels.
    for i in range(1, len(bars)):
        upper, lower = bars[i - 1], bars[i]
        prev, curr = gaps[i - 1], gaps[i]
        between = list(range(upper + 1, lower))
        for r in between:
            for c in prev:
                out[r][c] = 2
        if between:
            lo, hi = min(prev + curr), max(prev + curr)
            for c in range(lo, hi + 1):
                out[between[-1]][c] = 2
        for c in curr:
            out[lower][c] = 2
    for r in range(bars[-1] + 1, h):
        for c in gaps[-1]:
            out[r][c] = 2
    return out

